import React, { useEffect, useState } from 'react';
import Box from '../components/Box';
import './HomePage.css';
import Menu from '../components/Menu';
import axios from 'axios';

const HomePage = () => {
  const [boxes, setBoxes] = useState([]);
  const [selectedBox, setSelectedBox] = useState(null);
  const [hoveredAction, setHoveredAction] = useState('');
  const [actionToConfirm, setActionToConfirm] = useState(null);

  useEffect(() => {
    fetch('/data/boxes.json')
      .then((response) => response.json())
      .then((data) => setBoxes(data))
      .catch((error) => console.error('Error loading boxes:', error));
  }, []);

  const handleBoxClick = (box) => {
    setSelectedBox(box);
  };

  const confirmAction = async () => {
    if (actionToConfirm) {
      try {
        const response = await axios.post('http://localhost:3001/execute', {
          command: actionToConfirm.command,
        });
        alert(`Respuesta del servidor: ${response.data.stdout}`);
      } catch (error) {
        alert(`Error al ejecutar el comando: ${error.message}`);
      } finally {
        setActionToConfirm(null);
      }
    }
  };

  const handleActionClick = (action) => {
    if (action.label === 'print') {
      setHoveredAction(action);
    }
  };

  return (
    <div className="homepage">
      <h1>Home Page</h1>
      <div className="boxes-container">
        {boxes.map((box) => (
          <Box
            key={box.id}
            name={box.name}
            actions={box.actions}
            onClick={handleBoxClick}
            onMouseOver={handleActionClick}
            onMouseOut={handleActionClick}
          />
        ))}
      </div>
      <div className="action-confirm">
        {actionToConfirm && (
          <div>
            <p>Confirmar acción: {actionToConfirm.command}</p>
            <button onClick={confirmAction}>Confirmar</button>
            <button onClick={() => setActionToConfirm(null)}>Cancelar</button>
          </div>
        )}
      </div>
    </div>
  );
};

export default HomePage;
